insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('English', 'beginner', 'vocabulary', 'Greetings & Introductions', 'en-beg-vocab-greetings', 'Learn the most common English greetings and how to introduce yourself with confidence.', '{"sections":[{"type":"explanation","heading":"Why greetings matter","body":"Greetings are the first impression in any conversation. In English, the greeting you choose depends on the time of day and how formal the situation is. \"Hi\" and \"Hello\" are safe in almost every situation, while \"Good morning\" is slightly more formal. When you meet someone for the first time, it is polite to give your name and then ask for theirs with \"Nice to meet you\"."},{"type":"vocabulary","heading":"Core vocabulary","items":[{"word":"Hello / Hi","translation":"Halo / Hai","example":"Hi, my name is Sinta."},{"word":"Good morning","translation":"Selamat pagi","example":"Good morning, class!"},{"word":"Good afternoon","translation":"Selamat siang","example":"Good afternoon, Mr. David."},{"word":"Good evening","translation":"Selamat malam","example":"Good evening, everyone."},{"word":"Nice to meet you","translation":"Senang berkenalan dengan Anda","example":"I am Rina. Nice to meet you!"},{"word":"How are you?","translation":"Apa kabar?","example":"Hi Budi, how are you today?"}]},{"type":"dialog","heading":"Conversation: Meeting for the first time","lines":[{"speaker":"A","text":"Hello! I am Sinta. What is your name?","translation":"Halo! Saya Sinta. Siapa nama kamu?"},{"speaker":"B","text":"Hi Sinta, I am Budi. Nice to meet you.","translation":"Hai Sinta, saya Budi. Senang berkenalan."},{"speaker":"A","text":"Nice to meet you too. Where are you from?","translation":"Senang berkenalan juga. Kamu dari mana?"},{"speaker":"B","text":"I am from Bandung, Indonesia. And you?","translation":"Saya dari Bandung, Indonesia. Kalau kamu?"}]},{"type":"exercise","heading":"Practice","instructions":"Write your own introduction using at least four phrases from this lesson.","items":["Introduce yourself: name, city, and one fact about you.","Greet a teacher formally in the morning.","Ask a new friend how they are doing."]}]}'::jsonb, 1, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('English', 'beginner', 'grammar', 'Present Simple Tense', 'en-beg-gram-present-simple', 'Master the most used tense in English: routines, facts, and habits.', '{"sections":[{"type":"explanation","heading":"When to use the present simple","body":"The present simple describes habits, routines, facts, and things that are generally true. For example: \"I study English every day\" or \"Water boils at 100 degrees\". With he, she, and it, the verb takes an -s ending: \"She works at a bank\". To make questions and negatives, we use do/does: \"Do you like coffee?\", \"She does not watch TV\". Remember: after does, the main verb loses its -s."},{"type":"examples","heading":"Structure","items":[{"source":"I / You / We / They + verb","translation":"They study English at night."},{"source":"He / She / It + verb-s","translation":"She studies English at night."},{"source":"Do + subject + verb?","translation":"Do you play football on Sunday?"},{"source":"Does + subject + verb (no -s)?","translation":"Does he play football on Sunday?"}]},{"type":"vocabulary","heading":"Signal words","items":[{"word":"always","translation":"selalu","example":"I always drink tea in the morning."},{"word":"usually","translation":"biasanya","example":"She usually walks to school."},{"word":"sometimes","translation":"kadang-kadang","example":"We sometimes eat out on Friday."},{"word":"never","translation":"tidak pernah","example":"He never eats meat."},{"word":"every day","translation":"setiap hari","example":"I practice English every day."}]},{"type":"exercise","heading":"Practice","instructions":"Complete each sentence with the correct form of the verb in brackets.","items":["My sister ______ (go) to campus by bus.","______ you ______ (like) durian?","We ______ (not/work) on Sunday.","Andi ______ (brush) his teeth twice a day."]}]}'::jsonb, 2, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('English', 'beginner', 'daily', 'Ordering Food & Drinks', 'en-beg-daily-ordering-food', 'Order coffee, food, and snacks politely in cafés and restaurants.', '{"sections":[{"type":"explanation","heading":"Polite ordering patterns","body":"In English cafés and restaurants, politeness matters. Instead of commanding (\"Give me a coffee\"), use softeners like \"Can I have...\", \"Could I get...\", or \"I would like...\". These structures sound friendly and professional. Numbers and sizes are also important: a small, medium, or large drink, and \"for here or to go\" asks whether you eat in the shop or take the food away."},{"type":"vocabulary","heading":"Menu vocabulary","items":[{"word":"I would like…","translation":"Saya mau…","example":"I would like a medium latte, please."},{"word":"Could I get…","translation":"Bisa saya dapat…","example":"Could I get a glass of water?"},{"word":"for here / to go","translation":"di sini / dibungkus","example":"Is that for here or to go?"},{"word":"the bill / check","translation":"nota / tagihan","example":"Can I have the bill, please?"},{"word":"It is delicious","translation":"Enak sekali","example":"This soup is delicious!"}]},{"type":"dialog","heading":"Conversation: At a café","lines":[{"speaker":"Barista","text":"Good morning! What can I get for you?","translation":"Selamat pagi! Mau pesan apa?"},{"speaker":"Customer","text":"Hi, could I get a large cappuccino, please?","translation":"Hai, boleh saya pesan cappuccino ukuran besar?"},{"speaker":"Barista","text":"Sure. For here or to go?","translation":"Tentu. Di sini atau dibungkus?"},{"speaker":"Customer","text":"To go, please. How much is it?","translation":"Dibungkus. Berapa harganya?"}]},{"type":"exercise","heading":"Practice","instructions":"Rewrite each sentence using a polite ordering pattern.","items":["Give me one iced tea.","I want two donuts.","Bring me the bill now."]}]}'::jsonb, 3, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('English', 'intermediate', 'grammar', 'Past Simple vs Present Perfect', 'en-int-gram-past-vs-perfect', 'The classic intermediate confusion, explained with clear time signals.', '{"sections":[{"type":"explanation","heading":"Two pasts, two meanings","body":"The past simple is used for finished actions at a specific time in the past: \"I visited Bali last year\". The present perfect connects the past to the present: \"I have visited Bali three times\" (experience up to now) or \"I have just eaten\" (very recent result). If the sentence names a finished time — yesterday, last week, in 2019, two days ago — use the past simple. If the time is unfinished or unspecified — ever, never, already, yet, just, this week, since, for — the present perfect fits better."},{"type":"examples","heading":"Compare","items":[{"source":"I lost my phone yesterday.","translation":"HP saya hilang kemarin. (waktu spesifik → past simple)"},{"source":"I have lost my phone!","translation":"HP saya hilang! (hasil terasa sekarang → present perfect)"},{"source":"She worked in Jakarta in 2020.","translation":"Dia bekerja di Jakarta pada 2020."},{"source":"She has worked in Jakarta since 2020.","translation":"Dia bekerja di Jakarta sejak 2020 (masih sekarang)."}]},{"type":"exercise","heading":"Practice","instructions":"Choose the correct tense for each sentence.","items":["I ______ (see) that movie three times.","We ______ (go) to Singapore last month.","______ you ever ______ (try) sushi?","He ______ (not/finish) his homework yet."]}]}'::jsonb, 1, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('English', 'intermediate', 'reading', 'Reading: The Coffee Farmer', 'en-int-read-coffee-farmer', 'Read a short story about an Indonesian coffee farmer and test your comprehension.', '{"sections":[{"type":"reading","heading":"A Better Price","body":"Pak Manaf has grown coffee in the hills of Aceh for twenty years. For most of that time, middlemen decided the price of his beans, and his family often struggled to pay for school books. Three years ago, he joined a local cooperative. The cooperative sells the coffee directly to roasters overseas, and the farmers receive the payment within one week. Last season, Pak Manaf earned almost double what he made before. He has already used part of the money to buy a small drying machine, and next year he plans to plant a new variety that sells at a higher price. \"The coffee was always good,\" he says. \"Now the money is good too.\"","translation":"Pak Manaf menanam kopi di perbukitan Aceh selama dua puluh tahun. Selama sebagian besar waktu itu, tengkulak menentukan harga biji kopinya, dan keluarganya sering kesulitan membayar buku sekolah. Tiga tahun lalu, ia bergabung dengan koperasi lokal. Koperasi menjual kopi langsung ke roastery luar negeri, dan petani menerima pembayaran dalam satu minggu. Musim lalu, Pak Manaf hampir mendapat dua kali lipat penghasilannya sebelumnya.","questions":["Why did Pak Manaf join the cooperative?","How fast do farmers receive payment now?","What has he bought with his new income?"]},{"type":"vocabulary","heading":"Key words","items":[{"word":"middleman","translation":"tengkulak / perantara"},{"word":"cooperative","translation":"koperasi"},{"word":"roaster","translation":"penyangrai kopi"},{"word":"variety","translation":"varietas"}]}]}'::jsonb, 2, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('English', 'advanced', 'writing', 'Writing Formal Emails', 'en-adv-writ-formal-emails', 'Structure, tone, and set phrases for professional email writing.', '{"sections":[{"type":"explanation","heading":"The four-part structure","body":"A professional email has four parts. (1) A clear subject line that states the topic, not just \"Question\". (2) An opening that states the purpose in the first sentence: \"I am writing to ask about…\". (3) A body with one idea per paragraph, using connectors such as however, therefore, and in addition. (4) A closing that makes the requested action explicit: \"Could you confirm by Friday?\". Avoid slang, contractions are acceptable but modest, and always proofread for the difference between its and it is."},{"type":"examples","heading":"Set phrases","items":[{"source":"I am writing regarding…","translation":"Saya menulis terkait…"},{"source":"Thank you for your prompt reply.","translation":"Terima kasih atas balasan cepat Anda."},{"source":"Please find attached…","translation":"Terlampir kami sampaikan…"},{"source":"I look forward to hearing from you.","translation":"Saya menantikan kabar dari Anda."}]},{"type":"exercise","heading":"Practice","instructions":"Draft a 120-word email to a conference organizer asking about a missing invoice, using the four-part structure.","items":["Include a specific subject line.","State the purpose in sentence one.","End with a clear action and deadline."]}]}'::jsonb, 1, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('English', 'advanced', 'grammar', 'Conditionals: Zero to Third', 'en-adv-gram-conditionals', 'All four conditional patterns with meaning, form, and common mistakes.', '{"sections":[{"type":"explanation","heading":"Four patterns, four distances","body":"English has four main conditionals, each marking how real or imaginary a situation is. Zero conditional (If + present, present) describes facts: \"If you heat ice, it melts\". First conditional (If + present, will) describes real future possibilities: \"If it rains, we will cancel the trip\". Second conditional (If + past, would) imagines unlikely presents: \"If I won the lottery, I would travel\". Third conditional (If + had + past participle, would have) imagines a different past: \"If I had studied, I would have passed\". Common mistakes: using will in the if-clause, or mixing third-condition halves."},{"type":"examples","heading":"Compare","items":[{"source":"If you press this button, the machine starts.","translation":"Zero — fakta umum."},{"source":"If she calls, I will answer.","translation":"First — kemungkinan nyata."},{"source":"If I were you, I would negotiate.","translation":"Second — khayalan masa kini."},{"source":"If we had left earlier, we would have caught the flight.","translation":"Third — penyesalan masa lalu."}]},{"type":"exercise","heading":"Practice","instructions":"Name the conditional type, then correct the mistakes.","items":["If I will see him, I will tell him.","If she had asked me, I would help her.","If water reaches 0°C, it will freeze."]}]}'::jsonb, 2, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('Japanese', 'beginner', 'vocabulary', 'Basic Greetings: あいさつ', 'ja-beg-vocab-greetings', 'Essential Japanese greetings for daily life, from morning to night.', '{"sections":[{"type":"explanation","heading":"Aisatsu: the social glue of Japan","body":"In Japan, greetings (aisatsu) are considered basic manners. The greeting changes by time of day: ohayou gozaimasu in the morning, konnichiwa during the day, and konbanwa in the evening. When leaving home, people say itte kimasu (\"I am off\"), and the family answers itterasshai. Adding san after someone’s family name is the safe, polite default for addressing people."},{"type":"vocabulary","heading":"Core phrases","items":[{"word":"おはようございます (ohayou gozaimasu)","translation":"Selamat pagi","example":"おはようございます、田中さん。"},{"word":"こんにちは (konnichiwa)","translation":"Selamat siang"},{"word":"こんばんは (konbanwa)","translation":"Selamat malam"},{"word":"はじめまして (hajimemashite)","translation":"Senang berkenalan","example":"はじめまして、リナです。"},{"word":"ありがとう ございます (arigatou gozaimasu)","translation":"Terima kasih"},{"word":"すみません (sumimasen)","translation":"Maaf / permisi"}]},{"type":"dialog","heading":"Conversation: First meeting","lines":[{"speaker":"A","text":"はじめまして。ユキです。","translation":"Senang berkenalan. Saya Yuki."},{"speaker":"B","text":"はじめまして、アンドレです。よろしくお願いします。","translation":"Senang berkenalan, saya Andre. Mohon bantuannya."},{"speaker":"A","text":"お仕事は何ですか。","translation":"Pekerjaan Anda apa?"},{"speaker":"B","text":"学生です。","translation":"Saya mahasiswa."}]},{"type":"exercise","heading":"Practice","instructions":"Choose the correct greeting for each moment.","items":["07:30, meeting your neighbor while jogging.","14:00, entering a convenience store.","20:00, greeting your host family at dinner."]}]}'::jsonb, 1, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('Japanese', 'beginner', 'daily', 'Shopping Phrases: お店で', 'ja-beg-daily-shopping', 'Buy things, ask prices, and pay politely in Japanese shops.', '{"sections":[{"type":"explanation","heading":"Numbers and yen","body":"Shopping in Japan starts with numbers: en (yen) prices use counters like hyaku-en (100 yen) and sen-en (1,000 yen). Staff will often ask \"Ikura desu ka\" is what YOU ask them: \"Kore wa ikura desu ka\" means \"How much is this?\". Pointing and saying kore (this), sore (that near you), are (that over there) works even with a small vocabulary. When paying, the cashier usually says \"go-en desu\" for the amount; you can answer with a simple \"kore de onegai shimasu\" while handing the money."},{"type":"vocabulary","heading":"Useful phrases","items":[{"word":"これは いくらですか (kore wa ikura desu ka)","translation":"Ini harganya berapa?"},{"word":"これを ください (kore o kudasai)","translation":"Tolong berikan yang ini"},{"word":"カードで いいですか (kaado de ii desu ka)","translation":"Boleh bayar dengan kartu?"},{"word":"袋は いりません (fukuro wa irimasen)","translation":"Tidak perlu kantong"},{"word":"ありがとう ございました (arigatou gozaimashita)","translation":"Terima kasih (selesai)"}]},{"type":"dialog","heading":"Conversation: Buying a gift","lines":[{"speaker":"Customer","text":"すみません、これは いくらですか。","translation":"Permisi, ini berapa harganya?"},{"speaker":"Staff","text":"それは 八百円です。","translation":"Yang itu 800 yen."},{"speaker":"Customer","text":"じゃあ、これを ください。","translation":"Kalau begitu, saya ambil yang ini."},{"speaker":"Staff","text":"かしこまりました。八百円です。","translation":"Baik. 800 yen ya."}]}]}'::jsonb, 2, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('Japanese', 'intermediate', 'grammar', 'Particles は vs が', 'ja-int-gram-wa-ga', 'The particle distinction that separates beginners from real users of Japanese.', '{"sections":[{"type":"explanation","heading":"Topic versus subject","body":"は (wa) marks the topic — what the sentence is about — and gives background information. が (ga) marks the grammatical subject and often presents new information or emphasizes who/what does something. Compare: 私はリナです (As for me, I am Lina — introducing yourself in a conversation about people) versus 私がリナです (I am the Lina — identifying yourself among others). With question words like 何 or 誰, が is required: 何がありますか. In subordinate clauses, が is also standard."},{"type":"examples","heading":"Contrast","items":[{"source":"象は鼻が長いです。","translation":"Tentang gajah, hidungnya panjang. (topik + subjek dalam satu kalimat)"},{"source":"誰が来ましたか。— 田中さんが来ました。","translation":"Siapa yang datang? — Tanaka datang. (informasi baru → が)"},{"source":"コーヒーは好きですが、お茶は好きではありません。","translation":"Kopi saya suka, teh tidak. (kontras → は)"}]},{"type":"exercise","heading":"Practice","instructions":"Fill the blank with は or が and explain your choice.","items":["猫 ___ 好きですか。","私 ___ 学生です。","山田さん ___ 来ました。"]}]}'::jsonb, 1, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('Spanish', 'beginner', 'vocabulary', 'Primeras palabras: la gente y la casa', 'es-beg-vocab-first-words', 'Your first 15 Spanish words for people, home, and everyday objects.', '{"sections":[{"type":"explanation","heading":"Nouns have gender","body":"Every Spanish noun is masculine (el) or feminine (la). Most words ending in -o are masculine: el libro (the book). Most words ending in -a are feminine: la casa (the house). Learning the article together with the noun from day one saves you months of corrections later. Plurals add -s if the word ends in a vowel and -es if it ends in a consonant: libro → libros, ciudad → ciudades."},{"type":"vocabulary","heading":"First vocabulary","items":[{"word":"la casa","translation":"rumah","example":"Mi casa es pequeña."},{"word":"el libro","translation":"buku","example":"El libro es nuevo."},{"word":"la familia","translation":"keluarga","example":"Mi familia vive en Bogotá."},{"word":"el amigo / la amiga","translation":"teman (L/P)","example":"Ella es mi amiga."},{"word":"la mesa","translation":"meja","example":"El café está en la mesa."},{"word":"la puerta","translation":"pintu","example":"Cierra la puerta, por favor."}]},{"type":"exercise","heading":"Practice","instructions":"Write the article el or la for each noun: ___ problema, ___ noche, ___ mapa, ___ mano.","items":["el problema (exception)","la noche","el mapa (exception)","la mano (exception)"]}]}'::jsonb, 1, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('Spanish', 'beginner', 'daily', 'En el hotel', 'es-beg-daily-hotel', 'Check in, ask about breakfast, and solve small problems at a hotel.', '{"sections":[{"type":"explanation","heading":"Checking in","body":"At the reception you will hear \"¿Tiene una reserva?\" (Do you have a reservation?). Answer with \"Tengo una reserva a nombre de…\" (I have a reservation under the name of…). Useful questions include \"¿A qué hora es el desayuno?\" (What time is breakfast?) and \"¿Hay wifi gratis?\" (Is there free wifi?). If something is broken, say \"El aire acondicionado no funciona\" (The air conditioning does not work). Adding por favor keeps every request friendly."},{"type":"dialog","heading":"Conversation: Check-in","lines":[{"speaker":"Recepcionista","text":"Buenas tardes. ¿Tiene una reserva?","translation":"Selamat sore. Apakah Anda punya reservasi?"},{"speaker":"Huésped","text":"Sí, a nombre de María Santos.","translation":"Ya, atas nama Maria Santos."},{"speaker":"Recepcionista","text":"Perfecto. Su habitación es la 210, en el segundo piso.","translation":"Baik. Kamar Anda nomor 210, di lantai dua."},{"speaker":"Huésped","text":"Gracias. ¿A qué hora es el desayuno?","translation":"Terima kasih. Sarapan jam berapa?"}]}]}'::jsonb, 2, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;

insert into public.lessons (language, level, category, title, slug, summary, content, order_index, is_public)
values ('Spanish', 'intermediate', 'grammar', 'Ser vs Estar', 'es-int-gram-ser-estar', 'Two verbs for "to be" — identity versus state, with the DOCTOR/PLACE trick.', '{"sections":[{"type":"explanation","heading":"Identity vs condition","body":"Ser describes what something IS by nature: identity, origin, profession, permanent characteristics, time, and dates (DOCTOR: Description, Occupation, Characteristic, Time, Origin, Relationship). Estar describes a STATE or condition: location, mood, temporary situations, and progressive tenses (PLACE: Position, Location, Action, Condition, Emotion). The classic pair: \"Soy cansado\" would claim tiredness as your personality; \"Estoy cansado\" simply reports that you are tired right now."},{"type":"examples","heading":"Compare","items":[{"source":"Ella es médica.","translation":"Dia adalah dokter. (profesi → ser)"},{"source":"Ella está en el hospital.","translation":"Dia sedang di rumah sakit. (lokasi → estar)"},{"source":"La sopa es de tomate.","translation":"Supnya sup tomat. (identitas bahan)"},{"source":"La sopa está fría.","translation":"Supnya dingin. (kondisi sekarang)"}]},{"type":"exercise","heading":"Practice","instructions":"Choose ser or estar.","items":["Nosotros ______ de Indonesia.","El café ______ muy caliente.","Hoy ______ lunes."]}]}'::jsonb, 1, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, content = excluded.content, order_index = excluded.order_index;
